('node-6-3', 'phase-06-lesson-03-html5-semantic-architecture-structured-do', 'module-8', 3, 'Lesson 8.3: HTML5 Semantic Architecture & Structured Document Outlines', 'Prerequisites: Lesson 6.1', 'Prerequisites: Lesson 6.1 | Subtopics: 6 items', 'Systems project application', 220, 7, 1500.0, 150.0, '# Lesson 6.3: HTML5 Semantic Architecture & Structured Document Outlines

